"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8987],{58987:e=>{e.exports=JSON.parse('{"callId":"call_replacement_001","audioUrl":null,"duration":198,"segments":[{"startMs":0,"endMs":3800,"speaker":"ava","text":"Thank you for calling Northwind Heating and Air. I\'m Northwind\'s AI assistant. How can I help you today?"},{"startMs":4200,"endMs":14000,"speaker":"customer","text":"Hi there. My AC is from 2008 and I\'ve had it repaired twice already this summer. My tech friend told me I should probably just replace it at this point. I\'m wondering if someone could come out and give me an estimate."},{"startMs":14400,"endMs":24000,"speaker":"ava","text":"That\'s a really smart approach — at 18 years old and with multiple repairs this season, an estimate makes a lot of sense. Can I get your name and address?"},{"startMs":24400,"endMs":29000,"speaker":"customer","text":"Patricia Williams, 8834 Spicewood Springs Road."},{"startMs":29400,"endMs":42000,"speaker":"ava","text":"Thanks Patricia. I found your account — I can see you have a Goodman unit from 2008, and it looks like you\'ve had three service visits in the last two years. Our comfort advisor, Sam, specializes in replacement consultations and will give you honest good-better-best options, including financing. I have Sam available Thursday afternoon, 2 to 4pm, or Friday morning, 9 to 11am."},{"startMs":42400,"endMs":46000,"speaker":"customer","text":"Thursday afternoon is perfect."},{"startMs":46400,"endMs":60000,"speaker":"ava","text":"Great. I\'ve booked a free replacement estimate consultation with Sam for Thursday July 17th, 2 to 4pm at 8834 Spicewood Springs. He\'ll review your current system, measure your home, and put together options. No pressure and no cost for the estimate. Anything else I can help with?"},{"startMs":60400,"endMs":63000,"speaker":"customer","text":"No, that\'s great. Thank you."},{"startMs":63400,"endMs":68000,"speaker":"ava","text":"You\'re welcome Patricia. We\'ll see you Thursday afternoon. Have a wonderful day!"}],"extractedFields":{"name":"Patricia Williams","address":"8834 Spicewood Springs Road","issue":"Old AC unit — replacement estimate requested","urgency":"low","equipment":"Goodman AC 2008","preferredWindow":"Thursday afternoon"},"sentimentBySegment":[0,-0.3,0.4,0.3,0.5,0.7,0.8,0.8,0.9],"bookingCard":{"jobId":"job_today_015","window":{"start":"14:00","end":"16:00","date":"2026-07-17"},"techName":"Sam Okafor"},"reasoning":"Customer has 18-year-old system with repeated repairs — high replacement lead probability. Equipment age and repair history flagged. Comfort Advisor assigned rather than technician. Replacement lead flag set on created job."}')}}]);